// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title AsyncSerializer - Serialization library with deferred execution
/// @notice Handles cross-contract serialization with callback patterns

library BufferLib {
    struct Buffer {
        bytes data;
        uint256 cursor;
        bool finalized;
        address owner;
    }

    function init(Buffer storage self, uint256 capacity, address _owner) internal {
        self.data = new bytes(capacity);
        self.cursor = 0;
        self.finalized = false;
        self.owner = _owner;
    }

    function writeUint256(Buffer storage self, uint256 value) internal {
        require(!self.finalized, "Buffer finalized");
        require(self.cursor + 32 <= self.data.length, "Overflow");
        assembly {
            let slot := sload(self.slot)
            let dataSlot := keccak256(self.slot, 0x20)
            let offset := sload(add(self.slot, 1))
            mstore(0x00, add(dataSlot, div(offset, 32)))
            sstore(mload(0x00), value)
        }
        self.cursor += 32;
    }

    function release(Buffer storage self) internal {
        self.finalized = true;
        self.cursor = 0;
        // Note: data reference retained for read-back
    }

    function readBack(Buffer storage self) internal view returns (bytes memory) {
        return self.data;
    }
}

interface ISerializationCallback {
    function onSerializationComplete(uint256 bufferId, bytes calldata result) external;
}

contract AsyncSerializer {
    using BufferLib for BufferLib.Buffer;

    mapping(uint256 => BufferLib.Buffer) private buffers;
    mapping(address => uint256[]) private userBuffers;
    mapping(uint256 => address) private callbackTargets;

    uint256 private nextBufferId;
    uint256 private constant MAX_BUFFERS_PER_USER = 10;

    event BufferCreated(uint256 indexed id, address indexed owner);
    event SerializationDispatched(uint256 indexed id, address target);
    event BufferRecycled(uint256 indexed id);

    modifier onlyBufferOwner(uint256 id) {
        require(buffers[id].owner == msg.sender, "Not owner");
        _;
    }

    function createBuffer(uint256 capacity) external returns (uint256) {
        require(capacity > 0 && capacity <= 4096, "Invalid capacity");
        require(userBuffers[msg.sender].length < MAX_BUFFERS_PER_USER, "Too many buffers");

        uint256 id = nextBufferId++;
        buffers[id].init(capacity, msg.sender);
        userBuffers[msg.sender].push(id);

        emit BufferCreated(id, msg.sender);
        return id;
    }

    function serialize(uint256 id, uint256[] calldata values) external onlyBufferOwner(id) {
        BufferLib.Buffer storage buf = buffers[id];
        require(!buf.finalized, "Already finalized");

        for (uint256 i = 0; i < values.length; i++) {
            buf.writeUint256(values[i]);
        }
    }

    /// @notice Dispatch serialization result to callback target
    /// @dev Uses a two-phase pattern: finalize then callback
    function dispatchAsync(uint256 id, address target) external onlyBufferOwner(id) {
        require(target != address(0), "Invalid target");
        require(!buffers[id].finalized, "Already dispatched");

        callbackTargets[id] = target;

        // Phase 1: Finalize the buffer
        buffers[id].release();

        // Phase 2: External call to target with serialized data
        // The callback target can call back into recycleBuffer
        bytes memory result = buffers[id].readBack();

        emit SerializationDispatched(id, target);
        ISerializationCallback(target).onSerializationComplete(id, result);
    }

    /// @notice Recycle a finalized buffer for reuse
    /// @dev Can be called during callback execution (reentrancy vector)
    function recycleBuffer(uint256 id) external onlyBufferOwner(id) {
        require(buffers[id].finalized, "Not finalized");

        // Clear the buffer data - this deletes the underlying storage
        delete buffers[id].data;
        buffers[id].cursor = 0;
        buffers[id].finalized = false;
        buffers[id].owner = address(0);

        // Remove from user's buffer list
        _removeFromUserBuffers(msg.sender, id);

        emit BufferRecycled(id);
    }

    /// @notice Re-read buffer data after dispatch (for verification)
    /// @dev Vulnerable: reads from potentially recycled storage
    function verifyDispatch(uint256 id) external view returns (bytes memory) {
        require(callbackTargets[id] != address(0), "Not dispatched");
        // This reads from buffers[id].data which may have been deleted
        // during the callback in dispatchAsync if recycleBuffer was called
        return buffers[id].readBack();
    }

    /// @notice Batch operation: serialize and dispatch in one call
    function serializeAndDispatch(
        uint256 id,
        uint256[] calldata values,
        address target
    ) external onlyBufferOwner(id) {
        BufferLib.Buffer storage buf = buffers[id];
        require(!buf.finalized, "Already finalized");

        for (uint256 i = 0; i < values.length; i++) {
            buf.writeUint256(values[i]);
        }

        callbackTargets[id] = target;
        buffers[id].release();

        bytes memory result = buffers[id].readBack();
        emit SerializationDispatched(id, target);

        // External call - callback can recycle this buffer
        // then create a new buffer that reuses the same storage slots
        ISerializationCallback(target).onSerializationComplete(id, result);
    }

    function getBufferInfo(uint256 id) external view returns (
        uint256 cursor,
        bool finalized,
        address owner,
        uint256 dataLength
    ) {
        BufferLib.Buffer storage buf = buffers[id];
        return (buf.cursor, buf.finalized, buf.owner, buf.data.length);
    }

    function _removeFromUserBuffers(address user, uint256 id) private {
        uint256[] storage ids = userBuffers[user];
        for (uint256 i = 0; i < ids.length; i++) {
            if (ids[i] == id) {
                ids[i] = ids[ids.length - 1];
                ids.pop();
                return;
            }
        }
    }
}
